"""Deterministic coverage that every fixture path tests/e2e/proofread-recall.mjs
constructs actually resolves to a file on disk.

Why this file exists: the harness previously read
tests/fixtures/proofread/hebrew-recall/venue.md, which was renamed to
venue-example.md. `node --check` (the harness's only prior test coverage, in
TestEvalHarnessNodeCheck in tests/test_proofread_fixture.py) proves the file
parses as valid JS -- it says nothing about whether the string literals inside
it point at files that exist. That gap is exactly how the stale path reached a
release-gated suite unnoticed: `node --check` passed the whole time the harness
was broken. This test closes that gap by extracting every fixture path literal
the harness references and asserting each one resolves on disk, plus asserting
the harness names the current fixture directory/file and not either of its two
predecessors.

Owns only tests/e2e/proofread-recall.mjs (read-only) and this test file.
"""

import os
import re
import unittest

ROOT_DIR = os.path.dirname(os.path.abspath(__file__))
REPO_DIR = os.path.dirname(ROOT_DIR)
HARNESS_PATH = os.path.join(REPO_DIR, "tests", "e2e", "proofread-recall.mjs")
FIXTURE_DIR = os.path.join(ROOT_DIR, "fixtures", "proofread", "hebrew-recall")
AGENTS_DIR = os.path.join(REPO_DIR, "src", "agents")


def _read_source():
    with open(HARNESS_PATH, encoding="utf-8") as fh:
        return fh.read()


class TestFixtureLiteralsResolve(unittest.TestCase):
    """Every `join(FIXTURE_DIR, '<literal>')` call in the harness must name a
    file that actually exists in tests/fixtures/proofread/hebrew-recall/."""

    def test_every_fixture_dir_join_literal_exists_on_disk(self):
        source = _read_source()
        literals = re.findall(r"join\(FIXTURE_DIR,\s*'([^']+)'\)", source)
        # Guard against a harness edit that stops referencing fixtures via
        # FIXTURE_DIR entirely -- an empty extraction would make this test
        # vacuously pass, which defeats its purpose.
        self.assertGreater(
            len(literals),
            0,
            "no join(FIXTURE_DIR, '...') calls found -- did the harness change "
            "how it builds fixture paths? Update this test's extraction regex.",
        )
        missing = []
        for literal in literals:
            candidate = os.path.join(FIXTURE_DIR, literal)
            if not os.path.isfile(candidate):
                missing.append(literal)
        self.assertEqual(
            missing,
            [],
            f"harness references fixture file(s) that do not exist on disk: {missing} "
            f"(looked under {FIXTURE_DIR})",
        )

    def test_every_dot_md_or_dot_json_literal_in_harness_resolves(self):
        """Belt-and-suspenders: independent of the join(FIXTURE_DIR, ...) call
        shape, grep the raw source for any single-quoted .md/.json literal that
        looks like a fixture filename (no path separators -- a bare filename,
        as every fixture reference in this harness is) and confirm each one
        exists directly under the fixture directory."""
        source = _read_source()
        literals = re.findall(r"'([A-Za-z0-9_.-]+\.(?:md|json))'", source)
        self.assertGreater(len(literals), 0, "no .md/.json literals found in harness source")
        checked = set()
        missing = []
        for literal in literals:
            if literal in checked:
                continue
            checked.add(literal)
            candidate = os.path.join(FIXTURE_DIR, literal)
            if not os.path.isfile(candidate):
                missing.append(literal)
        self.assertEqual(
            missing,
            [],
            f"harness contains fixture-shaped filename literal(s) not found under "
            f"{FIXTURE_DIR}: {missing}",
        )

    def test_agent_prompt_names_resolve_to_real_agent_files(self):
        source = _read_source()
        agent_names = re.findall(r"loadAgentPrompt\('([^']+)'\)", source)
        self.assertGreater(
            len(agent_names),
            0,
            "no loadAgentPrompt(...) calls found -- did the harness change how "
            "it loads agent prompts? Update this test's extraction regex.",
        )
        missing = []
        for name in agent_names:
            candidate = os.path.join(AGENTS_DIR, f"{name}.md")
            if not os.path.isfile(candidate):
                missing.append(name)
        self.assertEqual(
            missing,
            [],
            f"harness references agent(s) with no matching src/agents/*.md file: {missing}",
        )


class TestNoStaleFixturePaths(unittest.TestCase):
    """The harness must reference the CURRENT fixture directory and filenames,
    never the ones they were renamed from."""

    def test_references_venue_example_not_old_venue(self):
        source = _read_source()
        self.assertIn(
            "'venue-example.md'",
            source,
            "harness no longer references venue-example.md -- did the fixture "
            "filename change again? Update this assertion to match.",
        )
        self.assertNotIn(
            "'venue.md'",
            source,
            "harness still references the old, renamed-away venue.md fixture path",
        )

    def test_references_hebrew_recall_not_old_katharsis(self):
        source = _read_source()
        self.assertIn(
            "hebrew-recall",
            source,
            "harness no longer references the hebrew-recall fixture directory",
        )
        self.assertNotIn(
            "katharsis",
            source,
            "harness still references the old, renamed-away katharsis fixture directory",
        )


if __name__ == "__main__":
    unittest.main()
